    "Each method below authenticates the same BTCBOX account. Linking requires a recent sign-in and proof of ownership of the new identity.": "以下の各方法は同じBTCBOXアカウントを認証します。新しい本人情報を連携するには、最近のログインと所有権の確認が必要です。",
