    "No linked Google account or wallet is available for password recovery. Contact support before changing your sign-in methods.": "Không có tài khoản Google hoặc ví đã liên kết để khôi phục mật khẩu. Hãy liên hệ hỗ trợ trước khi thay đổi phương thức đăng nhập.",
    "If linking reports that your sign-in is no longer recent, sign out and sign back in, then retry. Identity linking never moves balances or merges two existing BTCBOX accounts.": "Nếu hệ thống báo lần đăng nhập đã quá lâu khi liên kết, hãy đăng xuất, đăng nhập lại rồi thử lại. Việc liên kết danh tính không chuyển số dư hoặc hợp nhất hai tài khoản BTCBOX hiện có.",
    "BTCBOX password": "Mật khẩu BTCBOX",
    "BTCBOX credentials could not be saved.": "Không thể lưu thông tin đăng nhập BTCBOX.",
    "Verify my identity to reset my BTCBOX password. This signature proves wallet ownership only and does not authorize any blockchain transaction.": "Xác minh danh tính của tôi để đặt lại mật khẩu BTCBOX. Chữ ký này chỉ chứng minh quyền sở hữu ví và không cho phép bất kỳ giao dịch blockchain nào.",
    "The verification has expired. Please verify your existing sign-in method again.": "Xác minh đã hết hạn. Vui lòng xác minh lại phương thức đăng nhập hiện có.",
    "Reverify my existing BTCBOX sign-in identity before linking another method. This signature proves wallet ownership only and does not authorize any blockchain transaction.": "Xác minh lại danh tính đăng nhập BTCBOX hiện có trước khi liên kết phương thức khác. Chữ ký này chỉ chứng minh quyền sở hữu ví và không cho phép giao dịch blockchain.",
    "Existing sign-in method verified. Now choose the new method to connect.": "Phương thức đăng nhập hiện tại đã được xác minh. Bây giờ hãy chọn phương thức mới để kết nối.",
    "Existing wallet verification failed.": "Xác minh ví hiện có thất bại.",
    "Link this new wallet to my existing BTCBOX account. This signature verifies wallet ownership only and does not authorize any blockchain transaction.": "Liên kết ví mới này với tài khoản BTCBOX hiện có của tôi. Chữ ký này chỉ xác minh quyền sở hữu ví và không cho phép giao dịch blockchain.",
    "Sign in to BTCBOX. This signature verifies wallet ownership only and does not authorize any blockchain transaction.": "Đăng nhập BTCBOX. Chữ ký này chỉ xác minh quyền sở hữu ví và không cho phép bất kỳ giao dịch blockchain nào.",
    "Authentication is still initializing. Reload and try again.": "Hệ thống xác thực vẫn đang khởi tạo. Hãy tải lại trang và thử lại.",
    "Enter your authenticator code to finish verifying your existing Google sign-in method.": "Nhập mã ứng dụng xác thực để hoàn tất xác minh phương thức đăng nhập Google hiện có.",
    "The Google identity has been linked to this BTCBOX account.": "Danh tính Google đã được liên kết với tài khoản BTCBOX này.",
