    "A saved payout reference could not be read. Check the withdrawal status and chain transaction before entering a new reference.": "Không thể đọc mã tham chiếu thanh toán đã lưu. Hãy kiểm tra trạng thái rút tiền và giao dịch trên chuỗi trước khi nhập mã mới.",
