    "A saved manual-credit request is unreadable. Check the user's ledger before creating another credit.": "Không thể đọc yêu cầu ghi có thủ công đã lưu. Hãy kiểm tra sổ cái của người dùng trước khi tạo khoản ghi có khác.",
