    "Each method below authenticates the same BTCBOX account. Linking requires a recent sign-in and proof of ownership of the new identity.": "Jede der folgenden Methoden authentifiziert dasselbe BTCBOX-Konto. Für eine Verknüpfung sind eine kürzlich erfolgte Anmeldung und ein Eigentumsnachweis der neuen Identität erforderlich.",
