    "First reverify a sign-in method already connected to this BTCBOX account. Then verify the new method you want to add. The two proofs must be different.": "Bestätigen Sie zuerst erneut eine bereits mit diesem BTCBOX-Konto verknüpfte Anmeldemethode. Bestätigen Sie anschließend die neue Methode, die Sie hinzufügen möchten. Beide Nachweise müssen unterschiedlich sein.",
