    "No linked Google account or wallet is available for password recovery. Contact support before changing your sign-in methods.": "Für die Passwortwiederherstellung ist kein verknüpftes Google-Konto und keine Wallet verfügbar. Wenden Sie sich an den Support, bevor Sie Ihre Anmeldemethoden ändern.",
    "If linking reports that your sign-in is no longer recent, sign out and sign back in, then retry. Identity linking never moves balances or merges two existing BTCBOX accounts.": "Wenn beim Verknüpfen gemeldet wird, dass Ihre Anmeldung nicht mehr aktuell ist, melden Sie sich ab und erneut an und versuchen Sie es noch einmal. Das Verknüpfen von Identitäten verschiebt niemals Guthaben und führt keine bestehenden BTCBOX-Konten zusammen.",
    "BTCBOX password": "BTCBOX-Passwort",
    "BTCBOX credentials could not be saved.": "BTCBOX-Zugangsdaten konnten nicht gespeichert werden.",
