    "The verification has expired. Please verify your existing sign-in method again.": "Die Verifizierung ist abgelaufen. Bitte bestätigen Sie Ihre bestehende Anmeldemethode erneut.",
    "Reverify my existing BTCBOX sign-in identity before linking another method. This signature proves wallet ownership only and does not authorize any blockchain transaction.": "Bestätigen Sie meine bestehende BTCBOX-Anmeldeidentität erneut, bevor Sie eine weitere Methode verknüpfen. Diese Signatur weist nur den Besitz der Wallet nach und autorisiert keine Blockchain-Transaktion.",
